code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    row_walls = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_walls = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_edges = [-1] + row_walls + [h]
    col_edges = [-1] + col_walls + [w]
    row_spans = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_spans = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]
    points = {}
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v not in (0, 8):
                        points.setdefault(v, set()).add((ri, ci))
    out = [[8 if grid[r][c] == 8 else 0 for c in range(w)] for r in range(h)]
    for color, pts in points.items():
        rows = {}
        cols = {}
        for r, c in pts:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)
        cells = set()
        for r, cs in rows.items():
            if len(cs) > 1:
                cells.update((r, c) for c in range(min(cs), max(cs) + 1))
        for c, rs in cols.items():
            if len(rs) > 1:
                cells.update((r, c) for r in range(min(rs), max(rs) + 1))
        for ri, ci in cells:
            r0, r1 = row_spans[ri]
            c0, c1 = col_spans[ci]
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if out[r][c] == 0 or out[r][c] == color:
                        out[r][c] = color
                    else:
                        out[r][c] = 6
    return out
